gtv(){return"\u0905\u0917\u0932\u0947 \u0938\u0947\u091f \u0915\u0947 \u0932\u093f\u090f \u0916\u093e\u0932\u0940 \u092a\u0902\u0915\u094d\u0924\u093f \u091c\u094b\u0921\u093c\u0924\u093e \u0939\u0948\u0964"},
gnI(){return"\u092e\u093e\u0907\u0928\u0938"},
gtu(){return"\u0906\u0916\u093f\u0930\u0940 \u0938\u0947\u091f \u0939\u091f\u093e\u0924\u093e \u0939\u0948\u0964 \u0916\u093e\u0932\u0940 \u092a\u0902\u0915\u094d\u0924\u093f \u0924\u0941\u0930\u0902\u0924 \u092e\u093f\u091f\u0924\u0940 \u0939\u0948, \u092d\u0930\u0940 \u0939\u0941\u0908 \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0947 \u092c\u093e\u0926\u0964 \u0905\u0917\u0930 \u090f\u0915 \u0939\u0940 \u0938\u0947\u091f \u092c\u091a\u0947, \u092b\u093c\u0940\u0932\u094d\u0921 \u092c\u0938 \u0916\u093e\u0932\u0940 \u0939\u094b \u091c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964"},
gnK(){return"\u090f\u0915\u094d\u0938\u0930\u0938\u093e\u0907\u091c\u093c \u091a\u093e\u0930\u094d\u091f"},
