gvn(){return"\u0938\u094d\u0925\u093f\u0930 \u0932\u092f, \u091c\u093f\u0938 \u092a\u0930 \u0938\u093e\u0932\u094b\u0902 \u091a\u0932\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964 \u0938\u0947\u0936\u0928 \u092d\u093e\u0930\u0940 \u0939\u094b\u0902 \u0924\u094b \u0939\u0930 \u0915\u0941\u091b \u092e\u0939\u0940\u0928\u094b\u0902 \u092e\u0947\u0902 \u0938\u0915\u094d\u0930\u093f\u092f \u0930\u093f\u0915\u0935\u0930\u0940 \u0915\u093e \u0939\u092b\u093c\u094d\u0924\u093e \u0932\u0947\u0902 \u2014 \u0935\u091c\u093c\u0928 \u0930\u0941\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0938\u0947 \u092c\u0947\u0939\u0924\u0930, \u092a\u0939\u0932\u0947\u0964"},
gvl(){return"\u0938\u0947\u0936\u0928 \u092a\u093e\u0938-\u092a\u093e\u0938 \u0939\u0948\u0902, \u0914\u0930 \u0925\u0915\u093e\u0928 \u091a\u0941\u092a\u091a\u093e\u092a \u092c\u0922\u093c\u0924\u0940 \u0939\u0948\u0964 \u0939\u0930 \u0926\u094b-\u0924\u0940\u0928 \u092e\u0939\u0940\u0928\u0947 \u0938\u0915\u094d\u0930\u093f\u092f \u0930\u093f\u0915\u0935\u0930\u0940 \u0915\u093e \u0939\u092b\u093c\u094d\u0924\u093e \u0906\u092e\u0924\u094c\u0930 \u092a\u0930 \u092c\u093f\u0928\u093e \u092c\u094d\u0930\u0947\u0915 \u092a\u0940\u0938\u0924\u0947 \u0930\u0939\u0928\u0947 \u0938\u0947 \u092a\u094d\u0930\u0917\u0924\u093f \u092c\u0947\u0939\u0924\u0930 \u0930\u0916\u0924\u093e \u0939\u0948\u0964"},
gvo(){return"\u0932\u0917\u092d\u0917 \u0939\u0930 \u0926\u093f\u0928 \u092d\u093e\u0930 \u092a\u0930\u0964 \u0928\u0940\u0902\u0926 \u0914\u0930 \u0916\u093e\u0928\u093e \u0938\u093e\u0925 \u0926\u0947\u0902 \u0924\u094b \u091a\u0932 \u0938\u0915\u0924\u093e \u0939\u0948\u0964 \u0907\u0938 \u0932\u092f \u092e\u0947\u0902 \u092e\u0939\u0940\u0928\u0947 \u092e\u0947\u0902 \u0932\u0917\u092d\u0917 \u090f\u0915 \u092c\u093e\u0930 \u0938\u0915\u094d\u0930\u093f\u092f \u0930\u093f\u0915\u0935\u0930\u0940 \u0915\u093e \u0939\u092b\u093c\u094d\u0924\u093e \u091c\u094b\u0921\u093c\u094b\u0902 \u0914\u0930 \u0932\u093f\u0917\u093e\u092e\u0947\u0902\u091f \u0915\u0940 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u0926\u0947\u0916\u092d\u093e\u0932 \u0939\u0948, \u092a\u0940\u091b\u0947 \u0939\u091f\u0928\u093e \u0928\u0939\u0940\u0902\u0964"},
gvx(){return"\u092f\u0939\u0940 \u0935\u0939 \u0932\u092f \u0939\u0948 \u091c\u093f\u0938\u0947 \u0932\u094b\u0917 \u0938\u093e\u0932\u094b\u0902 \u0930\u0916\u0924\u0947 \u0939\u0948\u0902\u0964"},
gvw(){return"\u0906\u092a \u0905\u0915\u094d\u0938\u0930 \u091f\u094d\u0930\u0947\u0928 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u2014 \u0910\u0938\u093e \u0936\u0947\u0921\u094d\u092f\u0942\u0932 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u0939\u0940\u0902 \u092c\u0928\u0924\u093e\u0964"},
gvy(){return"\u0932\u0917\u0924\u093e \u0939\u0948 \u0906\u092a\u0928\u0947 \u0936\u0930\u0940\u0930 \u0915\u093e \u0917\u0941\u092a\u094d\u0924 \u092e\u094b\u0921 \u0922\u0942\u0901\u0922 \u0932\u093f\u092f\u093e\u0964"},
gvB(){return"\u092d\u093e\u0930 \u0939\u093e\u0932 \u092e\u0947\u0902 \u092a\u0939\u0932\u0947 \u0939\u0940 \u0917\u093f\u0930 \u091a\u0941\u0915\u093e \u0939\u0948 \u2014 \u0938\u0915\u094d\u0930\u093f\u092f \u0930\u093f\u0915\u0935\u0930\u0940 \u0939\u094b \u091a\u0941\u0915\u0940 \u092e\u093e\u0928\u0940 \u091c\u093e \u0938\u0915\u0924\u0940 \u0939\u0948\u0964 \u0917\u0924\u093f \u092b\u093f\u0930 \u092a\u0915\u0921\u093c\u0947\u0902\u0964"},
