gmK(){return"Google Sheets"},
goc(){return"\u0936\u0947\u092f\u0930 \u092e\u0947\u0928\u0942 \u092e\u0947\u0902 \u090f\u0915 \u0936\u0940\u091f \u0916\u0941\u0932\u0947\u0917\u0940\u0964 \u0907\u0938\u0947 Google Sheets \u092f\u093e Excel \u092e\u0947\u0902 \u0916\u094b\u0932\u0947\u0902, \u0918\u0930 \u092a\u0930 \u092c\u0926\u0932\u0947\u0902, CSV \u0921\u093e\u0909\u0928\u0932\u094b\u0921 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092f\u0939\u093e\u0901 \u0906\u092f\u093e\u0924 \u0915\u0930\u0947\u0902\u0964 id \u0915\u0949\u0932\u092e \u0930\u0916\u0947\u0902, \u0924\u093e\u0915\u093f \u092b\u093c\u094b\u0928 \u092a\u0930 \u092e\u094c\u091c\u0942\u0926 \u0935\u0930\u094d\u0915\u0906\u0909\u091f \u0926\u094b\u092c\u093e\u0930\u093e \u0915\u0949\u092a\u0940 \u0928 \u0939\u094b\u0902, \u092c\u0932\u094d\u0915\u093f \u0905\u092a\u0921\u0947\u091f \u0939\u094b\u0902\u0964 JSON \u092c\u0948\u0915\u0905\u092a \u0905\u092c \u092d\u0940 \u092a\u0942\u0930\u0940 \u0915\u0949\u092a\u0940 \u0939\u0948\u0964"},
goe(){return"\u0936\u0940\u091f \u0936\u0947\u092f\u0930 \u0915\u0930\u0947\u0902"},
gjP(){return"\u092f\u0939 \u092b\u093c\u093e\u0907\u0932 IronVibe \u0936\u0940\u091f \u0928\u0939\u0940\u0902 \u0939\u0948\u0964"},
goi(){return"\u0907\u0938 \u0936\u0940\u091f \u092e\u0947\u0902 \u0906\u092f\u093e\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u092a\u0902\u0915\u094d\u0924\u093f \u0928\u0939\u0940\u0902 \u0939\u0948\u0964"},
gol(){return"\u092f\u0939 \u0928\u093f\u091c\u0940 \u0921\u093e\u092f\u0930\u0940 \u0939\u0948\u0964 \u0907\u0938\u0947 \u0916\u0941\u0926 \u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u0935\u093e\u0932\u0947 \u092e\u094b\u0921 \u092e\u0947\u0902 \u0906\u092f\u093e\u0924 \u0915\u0930\u0947\u0902\u0964"},
gog(){return"\u092f\u0939 \u0915\u094b\u091a \u0915\u0940 \u0936\u0940\u091f \u0939\u0948\u0964 \u0907\u0938\u0947 \u0926\u0942\u0938\u0930\u094b\u0902 \u0915\u094b \u091f\u094d\u0930\u0947\u0928 \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0947 \u092e\u094b\u0921 \u092e\u0947\u0902 \u0906\u092f\u093e\u0924 \u0915\u0930\u0947\u0902\u0964"},
goj(){return"\u092c\u0926\u0932\u0928\u0947 \u0915\u094b \u0915\u0941\u091b \u0928\u0939\u0940\u0902\u0964 \u092a\u0902\u0915\u094d\u0924\u093f\u092f\u093e\u0901 \u092a\u0939\u0932\u0947 \u0938\u0947 \u092e\u0947\u0932 \u0916\u093e\u0924\u0940 \u0939\u0948\u0902, \u092f\u093e \u0915\u0941\u091b \u091b\u094b\u0921\u093c \u0926\u0940 \u0917\u0908\u0902 \u0915\u094d\u092f\u094b\u0902\u0915\u093f \u090f\u0915 \u0926\u093f\u0928 \u092e\u0947\u0902 \u0915\u0908 \u0935\u0930\u094d\u0915\u0906\u0909\u091f \u0939\u0948\u0902 \u0914\u0930 id \u0915\u0949\u0932\u092e \u0928\u0939\u0940\u0902 \u0939\u0948\u0964"},
om(a,b,c,d,e){return"\u0905\u092a\u0921\u0947\u091f \u0915\u0930\u0928\u0947 \u0915\u0947 \u0935\u0930\u094d\u0915\u0906\u0909\u091f: "+a+"\u0964 \u091c\u094b\u0921\u093c\u0928\u0947 \u0915\u0947 \u0935\u0930\u094d\u0915\u0906\u0909\u091f: "+b+"\u0964 \u091c\u094b\u0921\u093c\u0928\u0947 \u0915\u0947 \u0915\u094d\u0932\u093e\u0907\u0902\u091f: "+c+"\u0964 \u0905\u092a\u0921\u0947\u091f \u0915\u0930\u0928\u0947 \u0915\u0947 \u0915\u094d\u0932\u093e\u0907\u0902\u091f: "+d+"\u0964 \u091b\u094b\u0921\u093c\u0940 \u0917\u0908 \u092a\u0902\u0915\u094d\u0924\u093f\u092f\u093e\u0901: "+e+"\u0964 \u092b\u093c\u093e\u0907\u0932 \u092e\u0947\u0902 \u0928 \u0939\u094b\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u0930\u094d\u0915\u0906\u0909\u091f \u092b\u093c\u094b\u0928 \u092a\u0930 \u0930\u0939\u0947\u0902\u0917\u0947\u0964 \u092b\u093c\u093e\u0907\u0932 \u0915\u093e \u0935\u0930\u094d\u0915\u0906\u0909\u091f \u0905\u092a\u0928\u0947 \u0938\u0947\u091f \u092c\u0926\u0932 \u0926\u0947\u0924\u093e \u0939\u0948\u0964"},
