goj(){return"\u041c\u0435\u043d\u044f\u0442\u044c \u043d\u0435\u0447\u0435\u0433\u043e. \u0421\u0442\u0440\u043e\u043a\u0438 \u0443\u0436\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0442, \u043b\u0438\u0431\u043e \u0447\u0430\u0441\u0442\u044c \u043f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u0430: \u0432 \u043e\u0434\u0438\u043d \u0434\u0435\u043d\u044c \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u043a, \u0430 \u0441\u0442\u043e\u043b\u0431\u0446\u0430 id \u043d\u0435\u0442."},
